range.addEventListener('keydown',stop);
const ease=x=>x<.5?2*x*x:1-Math.pow(-2*x+2,2)/2;
const play=()=>{
if(still){set(50);return}
stop();playing=true;box.classList.add('is-demo');
const t0=performance.now(),D=3200;
const tick=n=>{if(!playing)return;const t=(n-t0)/D;
let v;if(t<.18)v=100;else if(t<.58)v=100-100*ease((t-.18)/.4);else if(t<.74)v=0;else if(t<1)v=50*ease((t-.74)/.26);else{set(50);stop();return}
set(v);raf=requestAnimationFrame(tick)};
raf=requestAnimationFrame(tick);
};
