const sum = order.summary || {};
$('payPlan').textContent = (order.kind !== 'topup' && sum.months ? headOf(sum.title, sum.months) : '') || order.plan_name || '';
$('paySummary').textContent = summaryOf(order);
$('payAmount').textContent = fa(order.amount);
