$('payCardWarn').hidden = !!order.card;
$('payCopy').disabled = !order.card;
$('payAuto').hidden = !order.card;
view.live.querySelector('.pay-figure--timer').hidden = !order.card;
view.live.querySelector('.pay-timer').hidden = !order.card;
